fn sqlite_snapshot_semio_drawing_independent_path_style_query_and_text_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT text,name FROM semio_drawing_text JOIN semio_drawing_style ON style_id=semio_drawing_style.id').get().name!=='')throw Error('style reference');if(db.query('SELECT count(*) AS n FROM semio_drawing_segment').get().n!==6)throw Error('segments');db.query(\"UPDATE semio_drawing_text SET text='independently edited' WHERE style_id IS NOT NULL\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let DrawNode::Group{children,..}=&mut expected.layers[0].root{if let DrawNode::Text{value,..}=&mut children[1]{*value="independently edited".into();}}assert_eq!(r,expected);}

