yload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(interior);}let mut root=DrawNode::default();for _ in 0..f["nativeAdmission"]["maximumDepth"].as_u64().unwrap()+1{root=DrawNode::Group{transform:SemioTransform::identity(),children:vec![root]};}let deep=SemioDrawingSnapshot{layers:vec![DrawLayer{id:"deep".into(),root,..DrawLayer::default()}],..SemioDrawingSnapshot::default()};assert!(SemioDrawingSnapshot::decode_sqlite_snapshot_native(&store::os_io::IoPayload::Binary(deep.encode_pack()),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}

