#[test]
fn sqlite_snapshot_semio_drawing_borrowed_relational_component(){use std::io::Write;use std::process::{Command,Stdio};let(database,sql)=component_database();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let mut oracle=Command::new("bun").args(["-e","import{Database}from'bun:sqlite';const f=await Bun.file(process.argv[1]).json();const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA foreign_key_check').all().length)throw Error('relations');const x=d.query('SELECT child_id,artifact_kind,standard,subset,document_id FROM layout_drawing_component JOIN semio_drawing_document ON drawing_id=semio_drawing_document.id').get();if(JSON.stringify(Object.values(x))!==JSON.stringify(f.identity))throw Error('literal identity');d.close();",concat!(env!("CARGO_MANIFEST_DIR"),"/../../🏅️standards/🔖️v1/🪆️subsets/🖊️drawing/🚪️io/🪶️sqlite/📸️snapshot/🧫️fixtures/🧩️component.json")]).stdin(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&bytes).unwrap();let result=oracle.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let blob=database.table("semio_drawing_image").unwrap().rows[0].blob(6).unwrap();let pointer=blob.as_ptr();let restored=SemioDrawingSnapshot::reconstruct_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()),&sql).unwrap();assert_eq!(restored,fixture());assert_eq!(database.table("semio_drawing_image").unwrap().rows[0].blob(6).unwrap().as_ptr(),pointer);let rows=database.tables.iter().map(|t|t.rows.len()).sum::<usize>();assert!(SemioDrawingSnapshot::reconstruct_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows-1,..SqliteDatabaseLimits::default()}),&sql).is_err());assert!(SemioDrawingSnapshot::reconstruct_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()),&sql).is_err());}
